result:
   .width-add {
   width:90%;
   }
   .picBox {
       display: inline-block;
       cursor: pointer;
   }

   .form .goodsTitle {
       border-bottom: 1px solid rgba(0, 0, 0, 0.09);
       margin-bottom: 25px;
   }

   .form .goodsTitle ~ .goodsTitle {
       margin-top: 20px;
   }

   .form .goodsTitle .title {
       border-bottom: 2px solid #1890FF;
       padding: 0 8px 12px 5px;
       color: #000;
       font-size: 14px;
   }

   .form .goodsTitle .icons {
       font-size: 15px;
       margin-right: 8px;
       color: #999;
   }

   .form .add {
       font-size: 12px;
       color: #1890FF;
       padding: 0 12px;
       cursor: pointer;
   }

   .form .radio {
       margin-right: 20px;
   }

   .form .submission {
       width: 10%;
       margin-left: 27px;
   }

   .form .upLoad {
       width: 58px;
       height: 58px;
       line-height: 58px;
       border: 1px dotted rgba(0, 0, 0, 0.1);
       border-radius: 4px;
       background: rgba(0, 0, 0, 0.02);
   }

   .form .iconfont {
       color: #898989;
   }

   .form .pictrue {
       width: 60px;
       height: 60px;
       border: 1px dotted rgba(0, 0, 0, 0.1);
       margin-right: 10px;
   }

   .form .pictrue img {
       width: 100%;
       height: 100%;
   }

   .Modals .address {
       width: 90%;
   }

   .Modals .address .iconfont {
       font-size: 20px;
   }

	.form-submit {
	  /deep/.ivu-card{
	  	border-radius: 0;
	  }
    margin-bottom: 79px;

    .fixed-card {
           position: fixed;
           right: 0;
           bottom: 0;
           left: 200px;
           z-index: 29;
           box-shadow: 0 -1px 2px rgb(240, 240, 240);

           /deep/ .ivu-card-body {
               padding: 15px 16px 14px;
           }

           .ivu-form-item {
               margin-bottom: 0;
           }

           /deep/ .ivu-form-item-content {
               margin-right: 124px;
               text-align: center;
           }
       }
}
   .new_tab {
       >>>.ivu-tabs-nav .ivu-tabs-tab{
           padding:4px 16px 20px !important;
           font-weight: 500;
       }
   }
   .step_btn {
       margin: 0 10px 0;
   }
